define(
  "shell-modified",
  "The outer document differs from the sealed copy inside the payload.",
  {
    mount: false,
    code: "SHELL_MISMATCH",
    ok: false,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "mismatch",
    signature: "unsigned",
    expiry: "none",
  },
  async () => {
    const { html } = await buildContainer(base());
    // A comment, and nothing else: the shell is compared byte for byte because
    // an edit that looks harmless is exactly how a bootloader gets replaced.
    return {
      file: "shell-modified.dai.html",
      body: html.replace("<head>", "<head><!-- added after sealing -->"),
    };
  },
);

define(
  "signature-invalid",
  "Signed, then the signature bytes were altered. The manifest is otherwise intact.",
  {
    mount: false,
    code: "UNVERIFIED_SIGNATURE",
    ok: false,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "invalid",
    expiry: "none",
  },
  async () => {
    const { html } = await buildContainer(base({ signingKey: KEY }));
    const archive = archiveOf(html);
    const manifest = JSON.parse(new TextDecoder().decode(archive["runtime/manifest.json"]));
    const raw = Buffer.from(manifest.signature, "base64");
    raw[raw.length - 1] ^= 0xff;
    manifest.signature = raw.toString("base64");
    archive["runtime/manifest.json"] = bytes(JSON.stringify(manifest));
    return { file: "signature-invalid.dai.html", body: repack(html, archive) };
  },
);

define(
  "signed-entries-disagree",
  "The signed digest list disagrees with the digest list that was checked.",
  {
    mount: false,
    code: "SIGNED_SET_MISMATCH",
    ok: false,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "invalid",
    expiry: "none",
  },
  async () => {
    const { html } = await buildContainer(base({ signingKey: KEY, manifestVersion: 2 }));
    const archive = archiveOf(html);
    const manifest = JSON.parse(new TextDecoder().decode(archive["runtime/manifest.json"]));
    // The entry still hashes to what `hashes` claims, so every file checks out;
    // only the list the signature covers has been changed. An implementation
    // that verifies the signature without reconciling the two lists accepts a
    // signature over digests other than the ones it just checked.
    manifest.signedEntries["app/app.js"] = "0".repeat(64);
    archive["runtime/manifest.json"] = bytes(JSON.stringify(manifest));
    return { file: "signed-entries-disagree.dai.html", body: repack(html, archive) };
  },
);

define(
  "version-2-signed",
  "A version 2 container, still verified after the compiler moved to 3 (§9.1). The shell is in its signed set, as version 2 had it.",
  {
    mount: true,
    ok: true,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "valid",
    expiry: "none",
  },
  async () => ({
    file: "version-2-signed.dai.html",
    body: (await buildContainer(base({ signingKey: KEY, manifestVersion: 2 }))).html,
  }),
);

define(
  "signed-extra-entry",
  "A version 2 container with an entry added alongside a matching digest, the signed list untouched. Version 2 stays verified; it does not keep the hole.",
  {
    mount: false,
    code: "SIGNED_SET_MISMATCH",
    ok: false,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "invalid",
    expiry: "none",
  },
  async () => {
    const { html } = await buildContainer(base({ signingKey: KEY, manifestVersion: 2 }));
    const archive = archiveOf(html);
    const manifest = JSON.parse(new TextDecoder().decode(archive["runtime/manifest.json"]));
    // Every file checks out, including the new one: it is listed in `hashes`
    // with its true digest. Only `signedEntries` and the signature are as
    // they were. A reader that reconciles the signed list against `hashes`
    // in one direction only accepts this as authentic.
    const evil = bytes("console.log('not signed')");
    archive["app/evil.js"] = evil;
    manifest.hashes["app/evil.js"] = createHash("sha256").update(evil).digest("hex");
    archive["runtime/manifest.json"] = bytes(JSON.stringify(manifest));
    return { file: "signed-extra-entry.dai.html", body: repack(html, archive) };
  },
);

define(
  "signed-schema-injected",
  "A schema declaration added the same way. A host runs its migration SQL.",
  {
    mount: false,
    code: "SIGNED_SET_MISMATCH",
    ok: false,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "invalid",
    expiry: "none",
  },
  async () => {
    const { html } = await buildContainer(base({ signingKey: KEY, manifestVersion: 2 }));
    const archive = archiveOf(html);
    const manifest = JSON.parse(new TextDecoder().decode(archive["runtime/manifest.json"]));
    // The same trick, aimed at the one unsigned entry a host executes:
    // migration SQL from a schema the publisher never declared, run against
    // the person's data under the publisher's badge.
    const schema = bytes(
      JSON.stringify({
        version: 2,
        tables: {},
        migrations: [{ version: 2, from: 1, to: 2, sql: "DROP TABLE IF EXISTS notes" }],
      }),
    );
    archive["runtime/schema.json"] = schema;
    manifest.hashes["runtime/schema.json"] = createHash("sha256").update(schema).digest("hex");
    archive["runtime/manifest.json"] = bytes(JSON.stringify(manifest));
    return { file: "signed-schema-injected.dai.html", body: repack(html, archive) };
  },
);

define(
  "sectioned-valid",
  "The sectioned binary form, unmodified.",
  {
    mount: true,
    ok: true,
    entries: { mismatched: [], missing: [], unlisted: [] },
    shell: "ok",
    signature: "unsigned",
    expiry: "none",
    sections: { mismatched: [], missing: [], staleFooter: false },
  },
  async () => ({
    file: "sectioned-valid.dai",
    body: await toSectionedContainer(await buildContainer(base())),
  }),
);

define(
  "sectioned-payload-modified",
  "A byte inside the payload section no longer matches the section table.",
  {
    mount: false,
    code: "SECTION_MISMATCH",
    ok: false,
    shell: "ok",
    signature: "unsigned",
    expiry: "none",
    sections: { mismatched: [2], missing: [], staleFooter: false },
  },
  async () => {
    const file = await toSectionedContainer(await buildContainer(base()));
    // Located from the table rather than guessed. The first attempt at this
    // case flipped a byte at a fixed offset, which landed in the manifest and
    // produced a case whose name said one thing and whose contents said
    // another — caught here only because the expectation was written first.
    const { offset } = readContainerFile(file).sections.find(
      (section) => section.id === SECTION.PAYLOAD,
    );
    file[offset + 16] ^= 0xff;
    return { file: "sectioned-payload-modified.dai", body: file };
  },
);

define(
  "sectioned-stale-footer",
  "The footer records a database other than the one the file carries.",
  {
    mount: false,
    code: "DATA_DAMAGED",
    ok: false,
    shell: "ok",
    signature: "unsigned",
    expiry: "none",
    sections: { mismatched: [], missing: [], staleFooter: true },
  },
  async () => {
    const file = await toSectionedContainer(await buildContainer(base()));
    // The last four bytes are the footer magic; the digest sits at +8.
    file[file.length - 64 + 8] ^= 0xff;
    return { file: "sectioned-stale-footer.dai", body: file };
  },
);

define(
  "sectioned-missing-data",
  "The section table declares no database. Not an empty document: an incomplete file.",
  {
    mount: false,
    code: "SECTION_MISSING",
    ok: false,
    shell: "ok",
    signature: "unsigned",
    expiry: "none",
    sections: { mismatched: [], missing: [3], staleFooter: false },
  },
  async () => {
    const file = await toSectionedContainer(await buildContainer(base()));
    // Two sections instead of three: the entry stays in the file, and the count
    // stops anything from reading it.
    new DataView(file.buffer, file.byteOffset).setUint32(8, 2, true);
    return { file: "sectioned-missing-data.dai", body: file };
  },
);

define(
  "not-a-container",
  "An HTML document that is not a container at all. Refused before any check runs.",
  { mount: false, parses: false },
  async () => ({
    file: "not-a-container.html",
    body: "<!doctype html><title>Ordinary page</title><p>No payload here.</p>",
  }),
);

/** What our own reader concludes, reduced to the shape the suite states. */
async function observe(body) {
  const source = typeof body === "string" ? body : new Uint8Array(body);
  const parsed = parseContainer(source);
  const report = await auditContainer(parsed);

  // Whether a host may run this, taken from the function a host actually calls
  // rather than inferred from the report. The two are meant to agree, and a
  // suite that assumed they did could not notice the day they stopped.
  let mount = true;
  let code;
  try {
    await verifyContainer(source);
  } catch (error) {
    mount = false;
    code = error && error.code;
  }

  const named = (status) =>
    report.entries.filter((entry) => entry.status === status).map((entry) => entry.name).sort();

  const observed = {
    mount,
    ok: report.ok,
    entries: {
      mismatched: named("mismatch"),
      missing: named("missing"),
      unlisted: named("unlisted"),
    },
    shell: report.shell.status,
    signature: report.signature.status,
    expiry: report.expiry.status,
  };
  if (code) observed.code = code;

  if (report.sections) {
    observed.sections = {
      mismatched: report.sections.mismatched,
      missing: report.sections.missing,
      staleFooter: report.sections.staleFooter,
    };
  }

  return observed;
}

const disagreements = [];

rmSync(cases, { recursive: true, force: true });
mkdirSync(cases, { recursive: true });

const written = [];

for (const definition of definitions) {
  const { file, body } = await definition.make();
  writeFileSync(join(cases, file), typeof body === "string" ? body : Buffer.from(body));

  if (definition.expect.parses === false) {
    let parsed = true;
    try {
      parseContainer(body);
    } catch {
      parsed = false;
    }
    if (parsed) disagreements.push(`${definition.name}: expected this not to parse, and it did.`);
  } else {
    const observed = await observe(body);
    for (const [key, value] of Object.entries(definition.expect)) {
      const seen = JSON.stringify(observed[key]);
      const stated = JSON.stringify(value);
      if (seen !== stated) {
        disagreements.push(`${definition.name}: expected ${key} ${stated}, this reader said ${seen}.`);
      }
    }
  }

  written.push({
    name: definition.name,
    file: `cases/${file}`,
    form: file.endsWith(".dai") ? "sectioned" : "viewer",
    summary: definition.summary,
    expect: definition.expect,
  });
}

if (disagreements.length > 0) {
  // Not written. A suite whose expectations were quietly adjusted to match this
  // reader is a record of this reader, and the point is to have something that
  // can tell us we are wrong.
  console.error("This implementation disagrees with the stated expectations:\n");
  for (const line of disagreements) console.error(`  ${line}`);
  process.exit(1);
}

writeFileSync(
  join(suite, "cases.json"),
  JSON.stringify(
    {
      suiteVersion: 1,
      formatVersion: 2,
      specification: "docs/spec-v0.2.md",
      generatedBy: "scripts/build-conformance.mjs",
      cases: written,
    },
    null,
    2,
  ) + "\n",
);

console.log(`${written.length} cases written to conformance/cases.json`);

/*
 * Countersignature vectors (spec §9.4).
 *
 * A second key, generated once and kept beside the suite's signing key, signs
 * the same payload as a countersigner. The vector says which kid the reader
 * must find, what it must conclude when it holds that key, and what when it
 * holds none — "unheld", never a refusal.
 */
{
  const { countersign, countersignerHeader } = await import("../dist/cose.js");
  const { signedBytes, signedViewOf, fromBase64, toBase64, sha256Hex } = await import("../dist/core.js");
  const csKeyPath = join(suite, "countersign-key.pem");
  let csPem;
  if (existsSync(csKeyPath)) {
    csPem = readFileSync(csKeyPath, "utf8");
  } else {
    const pair = await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, true, ["sign", "verify"]);
    const pkcs8 = Buffer.from(await crypto.subtle.exportKey("pkcs8", pair.privateKey)).toString("base64");
    csPem = `-----BEGIN PRIVATE KEY-----\n${pkcs8.replace(/(.{64})/g, "$1\n")}\n-----END PRIVATE KEY-----\n`;
    writeFileSync(csKeyPath, csPem, "utf8");
  }
  const der = Buffer.from(csPem.replace(/-----[^-]+-----/g, "").replace(/\s+/g, ""), "base64");
  const privateKey = await crypto.subtle.importKey("pkcs8", der, { name: "ECDSA", namedCurve: "P-256" }, true, ["sign"]);
  const jwk = await crypto.subtle.exportKey("jwk", privateKey);
  const publicKey = await crypto.subtle.importKey("jwk", { kty: jwk.kty, crv: jwk.crv, x: jwk.x, y: jwk.y, ext: true }, { name: "ECDSA", namedCurve: "P-256" }, true, ["verify"]);
  const spki = new Uint8Array(await crypto.subtle.exportKey("spki", publicKey));
  const kidText = (await sha256Hex(spki)).slice(0, 16);
  const kid = new TextEncoder().encode(kidText);
  const kidHex = [...kid].map((b) => b.toString(16).padStart(2, "0")).join("");
  void countersignerHeader;

  const built = await buildContainer(base({ signingKey: KEY, manifestVersion: 3 }));
  const payload = signedBytes(signedViewOf(built.manifest));
  const envelope = await countersign(fromBase64(built.manifest.signature), payload, kid, async (bytes) =>
    new Uint8Array(await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, privateKey, bytes)),
  );
  const archive = archiveOf(built.html);
  const manifest = JSON.parse(new TextDecoder().decode(archive["runtime/manifest.json"]));
  manifest.signature = toBase64(envelope);
  archive["runtime/manifest.json"] = bytes(JSON.stringify(manifest));
  const file = "cases/countersignature-valid.dai.html";
  writeFileSync(join(suite, file), repack(built.html, archive));

  writeFileSync(
    join(suite, "countersign-vectors.json"),
    JSON.stringify(
      {
        suiteVersion: 1,
        generatedBy: "scripts/build-conformance.mjs",
        vectors: [
          {
            name: "countersignature-valid, key held",
            file,
            heldKeys: { [kidHex]: Buffer.from(spki).toString("base64") },
            expect: [{ kid: kidHex, status: "valid" }],
          },
          {
            name: "countersignature-valid, key not held",
            file,
            heldKeys: {},
            expect: [{ kid: kidHex, status: "unheld" }],
          },
        ],
      },
      null,
      2,
    ) + "\n",
  );
  console.log("countersignature vectors written to conformance/countersign-vectors.json");
}

/*
 * Trust vectors (spec §9.6 and §9.7).
 *
 * A sequence of signed documents and the state a conforming host must reach
 * after each, starting from an empty key store, recording each one it opens.
 * Two keys: the suite's signing key as the publisher, the countersign key as a
 * stranger. The names are the four collisions §9.7 names plus the one that
 * must not collide.
 */
{
  const csPem = readFileSync(join(suite, "countersign-key.pem"), "utf8");
  const steps = [
    { name: "first", key: KEY, publisherName: "Ace Space", expect: { state: "new" }, record: true },
    { name: "second", key: KEY, publisherName: "Ace Space", expect: { state: "known", count: 1 }, record: true },
    // Rule 1: one word, two alphabets. A Cyrillic а inside a Latin word.
    { name: "mixed-script", key: csPem, publisherName: "Ace Spаce", expect: { state: "conflict", rule: "mixed-script" }, record: false },
    // Rule 2: whole-script Cyrillic, every letter a UTS #39 prototype of a Latin one.
    { name: "cyrillic-skeleton", key: csPem, publisherName: "Асе Ѕрасе", expect: { state: "conflict", rule: "skeleton", knownAs: "Ace Space" }, record: false },
    // NFKC: fullwidth Latin.
    { name: "fullwidth", key: csPem, publisherName: "Ａｃｅ Ｓｐａｃｅ", expect: { state: "conflict", rule: "skeleton", knownAs: "Ace Space" }, record: false },
    // An all-CJK name must collide with nothing.
    { name: "cjk-no-collision", key: csPem, publisherName: "株式会社アクメ", expect: { state: "new" }, record: true },
    // Rule 3: a document this host has under one key, arriving under another.
    { name: "same-document-other-key", key: csPem, publisherName: "Northwind", uuidOf: "first", expect: { state: "conflict", rule: "document" }, record: false },
  ];
  // Every step is its own document. The suite's fixed UUID would make every
  // step the same document under two keys, which is rule 3's conflict — the
  // Python reader implemented the rule and failed four steps, correctly.
  const uuidFor = (name) => {
    const h = createHash("sha256").update("trust-vector:" + name).digest("hex");
    return `${h.slice(0, 8)}-${h.slice(8, 12)}-4${h.slice(13, 16)}-8${h.slice(17, 20)}-${h.slice(20, 32)}`;
  };
  const vectors = [];
  for (const step of steps) {
    const documentUuid = uuidFor(step.uuidOf ?? step.name);
    const built = await buildContainer(base({ signingKey: step.key, manifestVersion: 3, publisherName: step.publisherName, documentUuid }));
    const file = `cases/trust-${step.name}.dai.html`;
    writeFileSync(join(suite, file), built.html);
    vectors.push({ name: step.name, file, documentUuid, publisherName: step.publisherName, expect: step.expect, record: step.record });
  }
  writeFileSync(
    join(suite, "trust-vectors.json"),
    JSON.stringify({ suiteVersion: 1, generatedBy: "scripts/build-conformance.mjs", table: "confusables.json", sequence: vectors }, null, 2) + "\n",
  );
  console.log(`trust vectors written to conformance/trust-vectors.json (${vectors.length} steps)`);
}

/*
 * Identity vectors (spec §9.5 and §9.7).
 *
 * A test Fulcio and Rekor, minted here and published as the root a reader is
 * to hold. Each vector is a version 3 signed container whose manifest carries
 * a bundle — outside the signed set, so it is added after signing without
 * re-signing — and the verdict a reader holding that root must reach. The
 * root is regenerated with the suite; a reader holds what the file says.
 */
{
  const { testSigstore } = await import("./lib/sigstore-test.mjs");
  const { root, issue } = await testSigstore("Conformance Sigstore");
  const other = await testSigstore("Some other Sigstore");
  const built = await buildContainer(base({ signingKey: KEY, manifestVersion: 3 }));
  const parsedKey = parseContainer(built.html).publicKey;
  const signature = built.manifest.signature;
  const now = Math.floor(Date.now() / 1000);
  const stranger = await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, true, ["sign", "verify"]);
  const strangerSpki = Buffer.from(await crypto.subtle.exportKey("spki", stranger.publicKey)).toString("base64");

  const variants = [
    { name: "identity-valid", bundle: await issue({ subjectSpki: parsedKey, identity: "https://github.com/conformance", signatureB64: signature }), expect: { status: "shown", identity: "https://github.com/conformance", issuer: "https://accounts.example" } },
    { name: "identity-outside-window", bundle: await issue({ subjectSpki: parsedKey, identity: "https://github.com/conformance", signatureB64: signature, integratedTime: now, certWindow: [now - 7200, now - 3600] }), expect: { status: "absent" } },
    { name: "identity-wrong-key", bundle: await issue({ subjectSpki: strangerSpki, identity: "https://github.com/conformance", signatureB64: signature }), expect: { status: "absent" } },
    { name: "identity-unheld-root", bundle: await other.issue({ subjectSpki: parsedKey, identity: "https://github.com/conformance", signatureB64: signature }), expect: { status: "absent" } },
    { name: "identity-other-signature", bundle: await issue({ subjectSpki: parsedKey, identity: "https://github.com/conformance", signatureB64: (await buildContainer(base({ signingKey: KEY, manifestVersion: 3 }))).manifest.signature }), expect: { status: "absent" } },
  ];
  const vectors = [];
  for (const v of variants) {
    const archive = archiveOf(built.html);
    const manifest = JSON.parse(new TextDecoder().decode(archive["runtime/manifest.json"]));
    manifest.identity = v.bundle;
    archive["runtime/manifest.json"] = bytes(JSON.stringify(manifest));
    const file = `cases/${v.name}.dai.html`;
    writeFileSync(join(suite, file), repack(built.html, archive));
    // The container itself still verifies: identity is outside the signed set.
    const report = await auditContainer(parseContainer(readFileSync(join(suite, file), "utf8")));
    if (!report.ok) throw new Error(`${v.name}: the container should verify regardless of its bundle`);
    vectors.push({ name: v.name, file, expect: v.expect });
  }
  writeFileSync(
    join(suite, "identity-vectors.json"),
    JSON.stringify({ suiteVersion: 1, generatedBy: "scripts/build-conformance.mjs", roots: [root], vectors }, null, 2) + "\n",
  );
  console.log(`identity vectors written to conformance/identity-vectors.json (${vectors.length})`);
}

/*
 * The same documents, carried in links (§1.1).
 *
 * Only the intact viewer-form cases: a link is made from a document a reader
 * has already verified, and the sender refuses to pack a damaged one. The
 * damaged cases for the carrier are made by damaging a link, which the Python
 * runner does itself.
 */
const { packInline } = await import("../dist/inline.js");
const host = {
  template: readFileSync(join(repo, "dist/template.html"), "utf8"),
  runtime: readFileSync(join(repo, "dist/dai-runtime.js"), "utf8"),
};
const links = [];
for (const entry of written) {
  if (entry.form !== "viewer" || entry.expect.parses === false || entry.expect.ok !== true) continue;
  const html = readFileSync(join(suite, entry.file), "utf8");
  const value = await packInline(parseContainer(html), host);
  links.push({
    name: entry.name,
    link: `https://opener.example/#a=${value}`,
    expect: { ok: true, signature: entry.expect.signature, shell: "elided" },
  });
}
writeFileSync(
  join(suite, "inline-links.json"),
  JSON.stringify({ suiteVersion: 1, generatedBy: "scripts/build-conformance.mjs", links }, null, 2) + "\n",
);
console.log(`${links.length} links written to conformance/inline-links.json`);

/*
 * The isolation probe.
 *
 * Not a case: §4 describes a host, and no file can carry a verdict about one.
 * This is a container that runs the checks itself, from inside, and reports
 * what got through — so a host implementation has something to be measured by
 * rather than a paragraph to agree with.
 *
 * Built without the engine for the same reason the cases are: it tests the
 * boundary, not SQLite, and half a megabyte of WebAssembly would buy nothing.
 */
const probe = await buildContainer(
  base({
    files: Object.fromEntries(
      ["index.html", "probe.js", "probe.css"].map((name) => [
        name,
        readFileSync(join(suite, "isolation", name)),
      ]),
    ),
    appName: "Isolation probe",
    documentUuid: "6ba7b810-9dad-11d1-80b4-00c04fd430c8",
  }),
);

writeFileSync(join(suite, "isolation-probe.dai.html"), probe.html);
console.log("isolation probe written to conformance/isolation-probe.dai.html");
